mapper.select:
DECLARE @currDate DATE; DECLARE @preDateS DATE; DECLARE @preDateE DATE;
SET @currDate = CONVERT(DATE,#{edate});
SET @preDateS = DATEADD(MONTH, -1, @currDate); SET @preDateE = DATEADD(DAY, -1, @currDate);
SELECT TOP(1) ROW_NUMBER() OVER(ORDER BY Y1.J_DATE, Y1.IDX, Y1.SEQNO, Y1.LINNO) AS NUM , Y1.J_DATE , Y1.J_ID1 , Y1.J_CARRYID , Y1.J_BNUM , Y1.J_ID , Y1.GUBUN1 , Y1.IWEIGHT , Y1.DANGA , Y1.IKONGKEP , Y1.CKONGKEP , Y1.DAEGUBUN , Y1.K_JUKYO , Y1.K_CHA , Y1.K_DAE , Y1.J_BUGASE , Y1.KERATYPE , Y1.SEQNO , Y1.HALIN FROM ( SELECT '1' AS IDX , A.JUNPYOID , A.J_DATE AS J_DATE , A.TAXNO , A.J_ID1 , A.J_CARRYID , CAST(B.J_BNUM AS CHAR) AS J_BNUM , A.J_ID , C.GUBUN1 AS GUBUN1 , A.IWEIGHT AS IWEIGHT , A.DANGA AS DANGA , A.IKONGKEP AS IKONGKEP , A.CKONGKEP AS CKONGKEP , C.DAEGUBUN AS DAEGUBUN , D.ATEXT AS K_JUKYO , ISNULL(D.ACAMT,0) AS K_CHA , ISNULL(A.IKONGKEP ,0) AS K_DAE , ISNULL(A.BUGASE ,0) AS J_BUGASE , A.KERATYPE , D.SEQNO , D.LINNO , A.HALIN AS HALIN FROM INLIST A LEFT OUTER JOIN MESURING B ON A.J_ID = B.IPCHULGO_MAIPID LEFT OUTER JOIN JAJAE C ON A.J_SERIAL = C.J_SERIAL LEFT OUTER JOIN ACTRAN D ON A.J_ID = D.REF2 WHERE D.ACCOD = '0251' AND A.KERATYPE = '매입' AND A.J_DATE BETWEEN @preDateS AND @preDateE AND A.J_ID1 = #{J_ID1} UNION ALL SELECT '0' AS IDX , 0 AS JUNPYOID , CONVERT(VARCHAR(10),CONVERT(DATE,A.TDATE),23) AS J_DATE , '' , NULL , NULL , '' AS J_BNUM , '' , '' AS GUBUN1 , 0 AS IWEIGHT , 0 AS DANGA , A.ADAMT AS IKONGKEP , 0 AS CKONGKEP , '' AS DAEGUBUN , '' AS K_JUKYO , A.ACAMT AS K_CHA , 0 AS K_DAE , 0 AS J_BUGASE , '' AS KERATYPE , '' AS SEQNO , NULL AS LINNO , 0 AS HALIN FROM ACTRAN A WHERE A.TDATE BETWEEN CONVERT(VARCHAR(8),CONVERT(DATE,@preDateS),112) AND CONVERT(VARCHAR(8),CONVERT(DATE,@preDateE),112) AND A.CVCOD = #{J_ID1} AND A.ACCOD = '0251' AND A.ACAMT != 0 AND A.APVYN = 'Y' ) Y1

BEGIN TRY
		      BEGIN TRAN

			    DECLARE @ERROR_GB CHAR(1), @OUT_RESULT_MSG NVARCHAR(200) = NULL

                 UPDATE ACC_DEALER_CD
				    SET SCM_PSWD = #{SCMPW}
				  WHERE IDT_NO = #{IDT_NO}

		    	COMMIT TRAN;
		    	SET @ERROR_GB = '1';
			    SET @OUT_RESULT_MSG = '비밀번호 변경이 완료되었습니다.';

			END TRY 

	  BEGIN CATCH 
			ROLLBACK TRAN;
		    SET @ERROR_GB = '0';
		    SET @OUT_RESULT_MSG = CONCAT( '오류 메시지 : ', ERROR_MESSAGE()
			                            , '\r\n줄번호 : ', ERROR_LINE()
			  						    , '\r\n오류번호 : ', ERROR_NUMBER()
			  						    , '\r\n상태코드 : ', ERROR_STATE()
			  						    , '\r\n프로시저명 : ', ERROR_PROCEDURE()
			  						    , '\r\n심각도 : ', ERROR_SEVERITY()
			  						    , '\r\n오류줄번호 : ', @@ERROR);		     

		END CATCH

        SELECT @ERROR_GB AS RESULT
			 , @OUT_RESULT_MSG AS MSG
